static string Classify(string? name, double? hours) => (name, hours) switch
{
    (null or "", _) => "missing employee",
    (_, null) => "open entry",
    (_, < 0) => "invalid duration",
    (_, > 12) => "long shift",
    _ => "completed shift"
};

Console.WriteLine(Classify("Avery", 8));
